import{_ as e,o as t,c as r,a0 as i}from"./chunks/framework.DB31oXgM.js";const h=JSON.parse('{"title":"ADR 004: AI/ML Guardrails, Graceful Fallback & Kill Switch","description":"","frontmatter":{},"headers":[],"relativePath":"adr/004-ml-guardrails-and-killswitch.md","filePath":"adr/004-ml-guardrails-and-killswitch.md"}'),l={name:"adr/004-ml-guardrails-and-killswitch.md"};function n(s,a,o,c,d,u){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="adr-004-ai-ml-guardrails-graceful-fallback-kill-switch" tabindex="-1">ADR 004: AI/ML Guardrails, Graceful Fallback &amp; Kill Switch <a class="header-anchor" href="#adr-004-ai-ml-guardrails-graceful-fallback-kill-switch" aria-label="Permalink to &quot;ADR 004: AI/ML Guardrails, Graceful Fallback &amp; Kill Switch&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Machine learning models are integrated for cheat anomaly detection (Tier A) and adaptive jitter prediction (Tier A). However, ML models are probabilistic and must never compromise game correctness, introduce unbounded input lag, or false-punish legitimate players.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Graceful Degradation</strong>: If ML inference times out or fails, the engine instantly falls back to hardcoded deterministic rule engines (EWMA for jitter, static angular velocity thresholds for cheat detection).</li><li><strong>Bounded Output Range</strong>: Adaptive input delay adjustments are strictly bounded between 1 frame (16.6ms) and 5 frames (83.3ms), with maximum adjustment rate of 1 frame per 60 ticks.</li><li><strong>Flag, Never Auto-Ban</strong>: Anomaly detection models output suspicion scores; players are flagged for moderation review, never automatically banned by AI.</li><li><strong>Kill Switch</strong>: Operators can disable all ML subsystems via dynamic configuration flags with zero server downtime.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Simulation correctness and user experience are guaranteed even during complete ML failure.</li></ul>',9)])])}const f=e(l,[["render",n]]);export{h as __pageData,f as default};
